import{_ as l,l as r,o as e,c as n,v as t,p as h,x as o,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"机台匹配","description":"","frontmatter":{"title":"机台匹配","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tool-matching.md","filePath":"litho/tool-matching.md","lastUpdated":1789023840000}'),E={name:"litho/tool-matching.md"};function p(_,a,m,A,f,u){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="机台匹配" tabindex="-1">机台匹配 <a class="header-anchor" href="#机台匹配" aria-label="Permalink to &quot;机台匹配&quot;">​</a></h1><div class="epigraph"><p>同一套版、同一条胶，换一台扫描仪，CD 和套刻指纹会换一张脸。匹配不是把两台调成同一序列号，是把指纹差压进预算。</p><footer>—— 对照 tool matching / fingerprint matching；套刻指纹差见 [机台对机台套刻](/litho/tool-to-tool-overlay)</footer></div><p><a href="/litho/reticle-library-exchange">上一课</a>把版换进机。缺口是多机：量产不会只活在一台上。本课钉匹配，稼动率下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>照明瞳、镜头像差、台网格、剂量标定各台不同。混流后层间套刻和 CD 出现「机台条」。只校准单机到规格，不保证两机差。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选参考机，测照明、剂量、套刻网格、焦点。用校正表（照明、放大率、扫描同步偏置）把差压进剩余。统计：匹配残差进 SPC，超限停混流。与 <a href="/litho/scanner-calibration-cycle">扫描仪校准周期</a> 分工：校准是单机回到自己的零，匹配是两机相对零。</p>',7)),(e(),h(c,null,{default:o(()=>[d(i,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20REF%5B%22%E5%8F%82%E8%80%83%E6%9C%BA%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20DELTA%5B%22%E6%9C%BA%E5%B7%AE%22%5D%0A%20%20DUT%5B%22%E5%BE%85%E9%85%8D%E6%9C%BA%E6%8C%87%E7%BA%B9%22%5D%20--%3E%20DELTA%0A%20%20DELTA%20--%3E%20CORR%5B%22%E6%A0%A1%E6%AD%A3%E8%A1%A8%22%5D%0A%20%20CORR%20--%3E%20MIX%5B%22%E5%85%81%E8%AE%B8%E6%B7%B7%E6%B5%81%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>像差指纹通过 TCC 进 CD；网格指纹进套刻。校正若只做低阶（放大、旋转），高阶像差差仍在。High-NA 半场机差更刺眼。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课：匹配再好，机台不在线就没有产能。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>匹配管的是机差，不是单机绝对精度。</li><li>校正阶数必须覆盖混流敏感的指纹。</li><li>出处：套刻与照明课；校准周期课。</li></ul>',6))])}const C=l(E,[["render",p]]);export{T as __pageData,C as default};
